select 
from BOK_BALANCE bb
left join bok_bookset bok
on bb.bookset_id = bok.bookset_id
where bb.BOOKSET_ID=#{booksetId}
and (bb.SUBJECT_NO like '6%' or bb.subject_no='4003')
and to_char(bb.BALANCE_DATE,'yyyy-MM-dd')>=#{vdate}
and to_char(bb.BALANCE_DATE,'yyyy-MM-dd')<=#{mdate}

select 
from BOK_BALANCE bb
where bb.BOOKSET_ID=#{booksetId}
and bb.SUBJECT_NO like '6%'
and to_char(bb.BALANCE_DATE,'yyyy-MM-dd')>=#{vdate}
and to_char(bb.BALANCE_DATE,'yyyy-MM-dd')<=#{mdate}

select 
from BOK_BALANCE bb
where 1 = 1
and bb.SUBJECT_NO like '6%'
and to_char(bb.BALANCE_DATE,'yyyy-MM-dd')>=#{vdate}
and to_char(bb.BALANCE_DATE,'yyyy-MM-dd')<=#{mdate}
and (
	bb.BOOKSET_ID IN


			null) OR bb.BOOKSET_ID in (

		#{item.code}

)

select distinct sdl.ITEM_CODE id, sdl.ITEM_VALUE text from SYS_DATADICT_LIST sdl inner join SYS_DATADICT_LIST_LINK sdll on sdl.ITEM_CODE = sdll.ITEM_CODE
and sdll.LINKED_DICT_CODE = #{dict_code_parent}
and sdl.DICT_CODE = #{dict_code_child} and sdll.DICT_CODE = #{dict_code_child}
and TRIM(sdll.LINKED_ITEM_CODE) = TRIM(#{item_code_parent})
sdl.ITEM_VALUE like '%' || #{search} || '%'
ORDER BY sdl.ITEM_CODE asc

SELECT ins.bookset_id AS booksetId, ins.item_code AS itemNo , ins.item_name AS project , SUM(ins.item_amt) AS thistermamt FROM val_table_ins ins WHERE 1=1
AND ins.bookset_id=#{booksetId}
AND ins.bookset_id in
#{item}
AND ins.item_name = #{project}
AND ins.cdate >= to_date(#{vdate},'yyyy-mm-dd') AND ins.cdate <= to_date(#{mdate} ,'yyyy-mm-dd') GROUP BY ins.bookset_id, ins.item_code, ins.item_name ORDER BY ins.bookset_id , ins.item_code

SELECT ins.item_code AS itemNo , ins.item_name AS project, SUM(ins.item_amt) AS thistermamt FROM val_table_ins ins WHERE ins.cdate >= to_date(#{vdate},'yyyy-mm-dd') AND ins.cdate <= to_date(#{mdate},'yyyy-mm-dd') AND EXISTS( SELECT TMP.BOOKSET_ID FROM BOK_BOOKSET TMP WHERE TMP.bookset_id = ins.bookset_id
AND TMP.ACCT_MODE in
#{item}
)
AND ins.bookset_id in
#{item}
GROUP BY ins.item_code, ins.item_name ORDER BY ins.item_code

        SELECT BOOKSET_ID code,BOOKSET_NAME name,BOOKSET_NAME shortName,BOOKSET_ID hidCode FROM BOK_BOOKSET
        where 1=1

        			AND	BOOKSET_TYPE = #{booksetType}


	                AND	ACCT_MODE in 

	                    #{item}


        order by bookset_type,BOOKSET_ID
